def multitableinserts_sql(self, expression: exp.MultitableInserts) -> str:
    kind = self.sql(expression, "kind")

    if kind is None:
        if not getattr(self, "SUPPORTS_FROM_FIRST_MULTITABLE_INSERTS", False):
            self.unsupported("FROM-first multi-table INSERT is not supported")

        source = self.sql(expression, "source")
